const item = $input.first().json.body || $input.first().json;

const userId = item.userId || item.id || 'usr-anonymous';
const identifier = item.identifier || item.email || item.phone || 'unknown@resident.com';
const fullName = item.fullName || item.name || 'Resident';
const flatIdentifier = item.flatIdentifier || `${item.block || ''}-${item.flatNo || ''}` || 'General Resident';
const loginTime = item.loginTime || new Date().toISOString();
const ipAddress = item.ipAddress || '127.0.0.1';
const location = item.location || { city: 'Bangalore', country: 'IN', isp: 'Residential Broadband' };
const device = item.device || { browser: 'Chrome', os: 'Windows', deviceType: 'Desktop', userAgent: item.userAgent || 'Mozilla/5.0' };
const isNewDevice = Boolean(item.isNewDevice);
const failedAttemptsPrior = Number(item.failedAttemptsPrior || item.consecutiveFailures || 0);
const lastLoginTime = item.lastLoginTime || null;
const lastLoginLocation = item.lastLoginLocation || { city: 'Bangalore', country: 'IN' };
const loginStatus = item.loginStatus || (failedAttemptsPrior > 0 ? 'FAILED_PASSWORD' : 'SUCCESS');

const prompt = `You are the Chief Cyber-Security Guardian and Resident Account Protection Officer for Mana Community Society.
Analyze the following user authentication event in real-time to detect account takeover, impossible travel, credential stuffing, or anomalous behavior.

Authentication Session Telemetry:
- Resident ID: ${userId}
- Identifier: ${identifier}
- Resident Name: ${fullName}
- Flat / Unit: ${flatIdentifier}
- Attempt Timestamp: ${loginTime}
- Current IP Address: ${ipAddress}
- Geolocation: ${JSON.stringify(location)}
- Device Telemetry: ${JSON.stringify(device)}
- Is Unrecognized / New Device: ${isNewDevice}
- Consecutive Prior Failed Attempts: ${failedAttemptsPrior}
- Last Known Login: ${lastLoginTime || 'First recorded login'}
- Last Known Geolocation: ${JSON.stringify(lastLoginLocation)}
- Session Status: ${loginStatus}

Security Evaluation Guidelines:
1. Geo-Velocity / Impossible Travel: Flag if the geographical distance between last known login and current login cannot be physically traversed within the elapsed time.
2. Device & Fingerprint Anomaly: Check if an unknown browser/OS or server-side headless user-agent is mimicking resident behavior.
3. Brute-Force & Credential Stuffing: Multiple rapid failed attempts (> 3) indicate password guessing or credential leak exposure.
4. Risk Scoring: Assign a risk level (LOW, MEDIUM, HIGH, CRITICAL) and risk score (0 to 100).
5. Recommended Action:
   - ALLOW: Safe login session, normal access permitted.
   - REQUIRE_STEP_UP_OTP: Suspicious delta or new device, enforce mandatory 6-digit WhatsApp/SMS OTP challenge.
   - RESTRICTED_SESSION: Prohibit sensitive actions (financial dues payment, visitor pass generation, password changes).
   - BLOCK_AND_LOCKOUT: Active attack signature, temporarily lock account for 30 minutes and alert society security.
6. Urgent Security Alert: If risk is elevated or device is new, draft a concise WhatsApp/SMS warning to the resident with a one-tap secure/lock link.
7. Contextual Community Greeting: If login is verified & safe (LOW risk), generate a warm, contextual community micro-greeting suitable for their dashboard.

Respond ONLY with a valid JSON object matching this schema:
{
  "riskLevel": "LOW" | "MEDIUM" | "HIGH" | "CRITICAL",
  "riskScore": number (0 to 100),
  "isAnomalous": boolean,
  "recommendedAction": "ALLOW" | "REQUIRE_STEP_UP_OTP" | "RESTRICTED_SESSION" | "BLOCK_AND_LOCKOUT",
  "threatFactors": string[],
  "telemetryAudit": {
    "impossibleTravelDetected": boolean,
    "newDeviceEncountered": boolean,
    "bruteForceRisk": boolean,
    "locationDiscrepancy": string
  },
  "securityAlertMessage": string | null,
  "contextualGreeting": string,
  "adminAuditNote": "Concise rationale for security logs and SOC dashboard"
}`;

return [{
  json: {
    userId,
    identifier,
    fullName,
    flatIdentifier,
    loginTime,
    ipAddress,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedSecurity = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedSecurity = JSON.parse(rawText);
} catch (err) {
  parsedSecurity = {
    riskLevel: "LOW",
    riskScore: 5,
    isAnomalous: false,
    recommendedAction: "ALLOW",
    threatFactors: [],
    telemetryAudit: {
      impossibleTravelDetected: false,
      newDeviceEncountered: false,
      bruteForceRisk: false,
      locationDiscrepancy: "Standard resident session"
    },
    securityAlertMessage: null,
    contextualGreeting: "Welcome back to Mana Community! Have a productive and pleasant day.",
    adminAuditNote: "Session telemetry evaluated as regular resident activity."
  };
}

const meta = $('Prepare Login Security Audit Prompt').first().json;

return [{
  json: {
    status: "success",
    userId: meta.userId,
    identifier: meta.identifier,
    evaluatedAt: new Date().toISOString(),
    security: parsedSecurity
  }
}];
